import Database from "better-sqlite3";
import path from "path";

const DB_PATH = "/home/user/qwik-app/database.sqlite";

let db: Database.Database | null = null;

export function getDb(): Database.Database {
  if (!db) {
    db = new Database(DB_PATH);
    db.pragma("journal_mode = WAL");
    initializeSchema(db);
  }
  return db;
}

function initializeSchema(db: Database.Database): void {
  db.exec(`
    CREATE TABLE IF NOT EXISTS users (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT NOT NULL,
      email TEXT NOT NULL,
      age INTEGER NOT NULL
    )
  `);
}

export interface UserRow {
  name: string;
  email: string;
  age: string;
}

export interface ValidationError {
  row: number;
  errors: string[];
}

/**
 * Parse a CSV string into an array of UserRow objects.
 * Expects the first line to be the header: Name,Email,Age
 */
export function parseCSV(content: string): UserRow[] {
  const lines = content.split(/\r?\n/);
  const rows: UserRow[] = [];

  for (let i = 1; i < lines.length; i++) {
    const line = lines[i].trim();
    if (line === "") continue;

    const fields = parseCSVLine(line);
    rows.push({
      name: fields[0] ?? "",
      email: fields[1] ?? "",
      age: fields[2] ?? "",
    });
  }

  return rows;
}

/**
 * Parse a single CSV line respecting quoted fields.
 */
function parseCSVLine(line: string): string[] {
  const fields: string[] = [];
  let current = "";
  let inQuotes = false;

  for (let i = 0; i < line.length; i++) {
    const ch = line[i];

    if (inQuotes) {
      if (ch === '"') {
        if (i + 1 < line.length && line[i + 1] === '"') {
          current += '"';
          i++;
        } else {
          inQuotes = false;
        }
      } else {
        current += ch;
      }
    } else {
      if (ch === '"') {
        inQuotes = true;
      } else if (ch === ",") {
        fields.push(current.trim());
        current = "";
      } else {
        current += ch;
      }
    }
  }

  fields.push(current.trim());
  return fields;
}

/**
 * Validate a single row and return error messages.
 * Returns an empty array if the row is valid.
 */
export function validateRow(
  row: UserRow,
  rowIndex: number,
): string[] | null {
  const errors: string[] = [];

  // Name validation
  if (!row.name || row.name.trim() === "") {
    errors.push("Name cannot be empty");
  }

  // Email validation
  if (!isValidEmail(row.email)) {
    errors.push("Invalid email format");
  }

  // Age validation
  if (!isValidAge(row.age)) {
    errors.push("Age must be an integer >= 0");
  }

  return errors.length > 0 ? errors : null;
}

/**
 * Validate all rows. Returns an array of validation errors.
 * If the array is empty, all rows are valid.
 */
export function validateAllRows(rows: UserRow[]): ValidationError[] {
  const validationErrors: ValidationError[] = [];

  for (let i = 0; i < rows.length; i++) {
    const errors = validateRow(rows[i], i + 1);
    if (errors) {
      validationErrors.push({
        row: i + 1, // 1-based index
        errors,
      });
    }
  }

  return validationErrors;
}

/**
 * Check if an email is valid.
 * Must contain a non-empty username, @, and a non-empty domain.
 */
function isValidEmail(email: string): boolean {
  if (!email || email.trim() === "") return false;

  const atIndex = email.indexOf("@");
  if (atIndex <= 0) return false;

  const username = email.substring(0, atIndex);
  const domain = email.substring(atIndex + 1);

  if (username.trim() === "" || domain.trim() === "") return false;

  // Domain must contain at least one dot with something on both sides
  // e.g., "example.com"
  const dotIndex = domain.lastIndexOf(".");
  if (dotIndex <= 0 || dotIndex === domain.length - 1) return false;

  const domainPart = domain.substring(0, dotIndex);
  const tld = domain.substring(dotIndex + 1);

  if (domainPart.trim() === "" || tld.trim() === "") return false;

  return true;
}

/**
 * Check if age is a valid non-negative integer.
 */
function isValidAge(age: string): boolean {
  if (age === undefined || age === null || age.trim() === "") return false;

  // Must be an integer (no decimal point)
  if (!/^\d+$/.test(age.trim())) return false;

  const num = parseInt(age.trim(), 10);
  if (isNaN(num) || num < 0) return false;

  return true;
}

import type { RequestHandler } from "@builder.io/qwik-city";
import { getDb } from "~/lib/database";
import { parseCSV, validateAllRows } from "~/lib/csv";

export const onPost: RequestHandler = async ({ request, json }) => {
  const db = getDb();

  try {
    const formData = await request.formData();
    const file = formData.get("file");

    if (!file || !(file instanceof File)) {
      json(200, {
        success: false,
        imported: 0,
        errors: [
          {
            row: 0,
            errors: ["No file provided"],
          },
        ],
      });
      return;
    }

    const content = await file.text();
    const rows = parseCSV(content);

    if (rows.length === 0) {
      json(200, {
        success: false,
        imported: 0,
        errors: [
          {
            row: 0,
            errors: ["CSV file contains no data rows"],
          },
        ],
      });
      return;
    }

    // Validate all rows
    const validationErrors = validateAllRows(rows);

    if (validationErrors.length > 0) {
      json(200, {
        success: false,
        imported: 0,
        errors: validationErrors,
      });
      return;
    }

    // All rows valid - insert atomically in a transaction
    const insertStmt = db.prepare(
      "INSERT INTO users (name, email, age) VALUES (?, ?, ?)",
    );

    const insertAll = db.transaction(() => {
      let count = 0;
      for (const row of rows) {
        insertStmt.run(row.name.trim(), row.email.trim(), parseInt(row.age.trim(), 10));
        count++;
      }
      return count;
    });

    const imported = insertAll();

    json(200, {
      success: true,
      imported,
      errors: [],
    });
  } catch (err) {
    console.error("Import error:", err);
    json(200, {
      success: false,
      imported: 0,
      errors: [
        {
          row: 0,
          errors: ["Failed to process CSV file"],
        },
      ],
    });
  }
};

import type { RequestHandler } from "@builder.io/qwik-city";
import { getDb } from "~/lib/database";

export const onGet: RequestHandler = async ({ json }) => {
  const db = getDb();

  try {
    const users = db.prepare("SELECT id, name, email, age FROM users ORDER BY id ASC").all();
    json(200, users);
  } catch (err) {
    console.error("Users fetch error:", err);
    json(200, []);
  }
};

